/* Hidden attribute support */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #1e1e2f;
  --card-bg: #2b2b40;
  --accent-color: #ffd166;
  --accent-action: #06d6a0;
  --text-color: #f7fff7;
  --border-color: #073b4c;
  --danger-color: #ef476f;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-color);
  color: var(--text-color);
  font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.auction-card {
  background-color: var(--card-bg);
  border: 4px solid var(--accent-color);
  box-shadow: 8px 8px 0px var(--border-color);
  width: 100%;
  max-width: 420px;
  min-width: 320px;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.25rem;
  text-align: center;
}

.auction-header .auction-title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent-color);
  margin-bottom: 0.25rem;
}

.item-name {
  font-size: 1rem;
  opacity: 0.9;
}

.pixel-art-display {
  background-color: #151522;
  border: 4px solid var(--border-color);
  padding: 0.5rem;
  display: flex;
  justify-content: center;
  align-items: center;
}

#pixelCanvas {
  image-rendering: pixelated;
  display: block;
}

.auction-status {
  width: 100%;
  background: #202033;
  border: 2px solid var(--border-color);
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.status-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 1.1rem;
}

.value-price {
  font-weight: bold;
  font-size: 1.4rem;
  color: var(--accent-color);
}

.value-time {
  font-weight: bold;
  font-size: 1.3rem;
  color: var(--accent-action);
}

.value-time.warning {
  color: var(--danger-color);
}

.sold-banner {
  background-color: var(--accent-color);
  color: #1e1e2f;
  font-weight: bold;
  font-size: 1.25rem;
  padding: 0.75rem;
  border: 3px solid var(--border-color);
  margin-top: 0.5rem;
  animation: pulse 1s infinite alternate;
}

@keyframes pulse {
  0% { transform: scale(1); }
  100% { transform: scale(1.03); }
}

.bidding-controls {
  display: flex;
  width: 100%;
  gap: 1rem;
}

.pixel-btn {
  flex: 1;
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: bold;
  padding: 0.85rem;
  color: #1e1e2f;
  background-color: var(--accent-action);
  border: 3px solid var(--border-color);
  box-shadow: 4px 4px 0px var(--border-color);
  cursor: pointer;
  transition: transform 0.05s, box-shadow 0.05s, background-color 0.1s;
}

.pixel-btn:hover:not(:disabled) {
  background-color: #2bf0b6;
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--accent-color);
  outline-offset: 2px;
}

.pixel-btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0px var(--border-color);
}

.pixel-btn:disabled {
  background-color: #55556b;
  color: #8f8fa0;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
  border-color: #3b3b4d;
}

document.addEventListener('DOMContentLoaded', () => {
  let currentPrice = 10;
  let timeLeft = 45;
  let isAuctionOver = false;
  let timerId = null;

  const currentPriceEl = document.getElementById('currentPrice');
  const timerDisplayEl = document.getElementById('timerDisplay');
  const soldMessageEl = document.getElementById('soldMessage');
  const bid1Btn = document.getElementById('bid1Btn');
  const bid5Btn = document.getElementById('bid5Btn');
  const canvas = document.getElementById('pixelCanvas');

  // Draw pixel sword
  function drawPixelItem() {
    if (!canvas || !canvas.getContext) return;
    const ctx = canvas.getContext('2d');
    const pixelSize = 8;
    const matrix = [
      '                ',
      '              # ',
      '             ## ',
      '            ##o ',
      '           ##o  ',
      '          ##o   ',
      '         ##o    ',
      '        ##o     ',
      '   ==  ##o      ',
      '    ===#o       ',
      '     ===        ',
      '     x===       ',
      '    x   ==      ',
      '   x            ',
      '  x             ',
      '                '
    ];

    const colorMap = {
      '#': '#ffd166',
      'o': '#fff3b0',
      '=': '#ef476f',
      'x': '#06d6a0'
    };

    ctx.clearRect(0, 0, 128, 128);
    for (let row = 0; row < matrix.length; row++) {
      for (let col = 0; col < matrix[row].length; col++) {
        const char = matrix[row][col];
        if (colorMap[char]) {
          ctx.fillStyle = colorMap[char];
          ctx.fillRect(col * pixelSize, row * pixelSize, pixelSize, pixelSize);
        }
      }
    }
  }

  function updateDisplay() {
    currentPriceEl.textContent = currentPrice;
    timerDisplayEl.textContent = `${timeLeft}s`;

    if (timeLeft <= 10) {
      timerDisplayEl.classList.add('warning');
    } else {
      timerDisplayEl.classList.remove('warning');
    }
  }

  function endAuction() {
    isAuctionOver = true;
    if (timerId) {
      clearInterval(timerId);
      timerId = null;
    }
    timerDisplayEl.textContent = '0s';
    timerDisplayEl.classList.add('warning');
    bid1Btn.disabled = true;
    bid5Btn.disabled = true;

    soldMessageEl.textContent = `Sold for ${currentPrice}`;
    soldMessageEl.removeAttribute('hidden');
  }

  function tick() {
    if (isAuctionOver) return;
    timeLeft -= 1;
    if (timeLeft <= 0) {
      endAuction();
    } else {
      updateDisplay();
    }
  }

  function handleBid(amount) {
    if (isAuctionOver) return;

    currentPrice += amount;

    // If in the last 10 seconds, restart/reset to 10 seconds
    if (timeLeft <= 10) {
      timeLeft = 10;
    }

    updateDisplay();
  }

  // Event listeners
  bid1Btn.addEventListener('click', () => handleBid(1));
  bid5Btn.addEventListener('click', () => handleBid(5));

  // Initialize
  drawPixelItem();
  updateDisplay();
  timerId = setInterval(tick, 1000);
});
